{
  "findings": [
    {
      "check_id": "CKV2_AWS_61",
      "title": "S3 bucket lacks a lifecycle configuration",
      "resource": "aws_s3_bucket.financials",
      "severity": "MEDIUM",
      "explanation": "The financials bucket has no lifecycle configuration to clean up incomplete multipart uploads, which can leave unnecessary stored data and ongoing costs."
    },
    {
      "check_id": "CKV2_AWS_6",
      "title": "S3 bucket lacks a Public Access Block",
      "resource": "aws_s3_bucket.financials",
      "severity": "MEDIUM",
      "explanation": "Although the current ACL is private, no bucket-level Public Access Block prevents a future ACL or bucket policy from exposing financial data publicly."
    },
    {
      "check_id": "CKV_AWS_18",
      "title": "S3 access logging is not enabled",
      "resource": "aws_s3_bucket.financials",
      "severity": "HIGH",
      "explanation": "The bucket does not record S3 access requests, limiting the ability to investigate unauthorized access or changes involving financial data."
    },
    {
      "check_id": "CKV_AWS_144",
      "title": "S3 cross-region replication is not enabled",
      "resource": "aws_s3_bucket.financials",
      "severity": "MEDIUM",
      "explanation": "The financials bucket has no cross-region replication configuration, leaving its contents without a regionally isolated copy if the source region becomes unavailable."
    }
  ],
  "patched_code": "variable "financials_log_bucket" {
  description = "Name of a preconfigured S3 bucket in the same region that receives financials access logs."
  type        = string
}

variable "financials_replication_role_arn" {
  description = "ARN of an IAM role authorized to replicate objects from the financials bucket."
  type        = string
}

variable "financials_cross_region_replica_bucket_arn" {
  description = "ARN of a versioned S3 destination bucket in a different AWS region."
  type        = string
}

resource "aws_s3_bucket" "financials" {
  bucket        = "${local.resource_prefix.value}-financials"
  acl           = "private"
  force_destroy = true
  tags = merge({
    Name        = "${local.resource_prefix.value}-financials"
    Environment = local.resource_prefix.value
    }, {
  })
}

resource "aws_s3_bucket_public_access_block" "financials" {
  bucket = aws_s3_bucket.financials.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_lifecycle_configuration" "financials" {
  bucket = aws_s3_bucket.financials.id

  rule {
    id     = "abort-incomplete-multipart-uploads"
    status = "Enabled"

    filter {}

    abort_incomplete_multipart_upload {
      days_after_initiation = 7
    }
  }
}

resource "aws_s3_bucket_logging" "financials" {
  bucket        = aws_s3_bucket.financials.id
  target_bucket = var.financials_log_bucket
  target_prefix = "financials-access-logs/"
}

resource "aws_s3_bucket_versioning" "financials" {
  bucket = aws_s3_bucket.financials.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_replication_configuration" "financials" {
  bucket = aws_s3_bucket.financials.id
  role   = var.financials_replication_role_arn

  depends_on = [aws_s3_bucket_versioning.financials]

  rule {
    id     = "cross-region-replication"
    status = "Enabled"

    filter {}

    destination {
      bucket        = var.financials_cross_region_replica_bucket_arn
      storage_class = "STANDARD"
    }
  }
}
",
  "fix_summary": "Added a complete Public Access Block, lifecycle cleanup for incomplete multipart uploads, access logging, source versioning, and cross-region replication. The logging destination, replica bucket, and replication IAM role are supplied as variables so no credentials, secrets, or fabricated external resources are embedded."
}
